impl PartialEq for Server {
    fn eq(&self, other: &Server) -> bool {
        self.name == other.name && self.port == other.port && self.latency == other.latency
    }
}

impl Default for Server {
    fn default() -> Self {
        Server {
            name: String::new(),
            addresses: Vec::new(),
            port: 0,
            latency: Duration::new(0, 0),
        }
    }
}

async fn connect_to_server(server: &Server) -> Result<Connection> {
    let stream = TcpStream::connect((server.addresses[0], server.port))
        .map_err(|e| Error::Io(io::Error::new(io::ErrorKind::Other, e)))?;

    let connection = Connection::new(stream);
    Ok(connection)
}

async fn check_server_status(server: &Server) -> Result<ServerStatus> {
    let connection = connect_to_server(server).await?;
    let status_command = r.expr("status").run(connection).await?;
    Ok(status_command)
}

