                // Get an initial position.
                let mut position = Vector3 {
                    x: phi.cos() * prism_radius * radius,
                    y: phi.sin() * prism_radius * radius,
                    z: 0.0
                };
                let mut normal = Vector3::new(0.0, 0.0, -1.0);

                // Intersect with the floor to get the normal.
                let ray = Ray {
