pub fn load_document(&self, url: Url, load_type: LoadType) -> Result<(), String> {
    let resource_task = ResourceTask::new(url.clone(), load_type.clone());

    match self.pending_loads.insert(url.clone(), resource_task) {
        Ok(_) => {
            // Initiate the loading process
            if let Err(e) = load_whole_resource(&url) {
                self.pending_loads.remove(&url);
                return Err(format!("Failed to load resource: {}", e));
            }
            Ok(())
        },
        Err(_) => Err("Resource is already being loaded".to_string()),
    }
}

