    /// Mutably borrow the contents.
    ///
    /// This can panic if there are active borrows.
    pub fn borrow_mut(&self) -> RefMut<T> {
        self.value.borrow_mut()
    }

    /// Immutably borrow the contents.
    ///
    /// This can panic if there are active mutable borrows.
    pub fn borrow(&self) -> Ref<T> {
        self.value.borrow()
    }

    /// Check if the cell is currently borrowed.
    pub fn is_borrowed(&self) -> bool {
        self.value.borrow_state() != BorrowState::Empty
    }
