// GenerateBootstrapConfig generates the Envoy bootstrap configuration based on the BootstrapConfig fields.
func (c *BootstrapConfig) GenerateBootstrapConfig() (string, error) {
	var buf bytes.Buffer
	tmpl, err := template.New("bootstrap").Parse(c.Template())
	if err != nil {
		return "", fmt.Errorf("failed to parse bootstrap template: %w", err)
	}

	if err := tmpl.Execute(&buf, c); err != nil {
		return "", fmt.Errorf("failed to execute bootstrap template: %w", err)
	}

	return buf.String(), nil
}

// ResolveEnvVars resolves environment variables in the given URL string.
func ResolveEnvVars(urlStr string) (string, error) {
	if strings.HasPrefix(urlStr, "$") {
		envVar := strings.TrimPrefix(urlStr, "$")
		value, exists := os.LookupEnv(envVar)
		if !exists {
			return "", fmt.Errorf("environment variable %s not set", envVar)
		}
		return value, nil
	}
	return urlStr, nil
}

