	_params["mailing"] = mailing
	_params["primary"] = primary

	_cmd := map[string]interface{}{
		"/address/update-address": _params,
	}

	var v map[string]interface{}

	res, err := s.session.Invoke(_cmd)

	if err == nil && res != nil {
		v = res.(map[string]interface{})
	}

	return v, err
